// ValidateEvaluateConditionalAccessRequestBody runs the validations defined on
// evaluate_conditional_access_request_body
func ValidateEvaluateConditionalAccessRequestBody(body *EvaluateConditionalAccessRequestBody) (err error) {
	if body.UserID == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("user_id", "body"))
	}
	if body.ResourceID == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("resource_id", "body"))
	}
	if body.Action == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("action", "body"))
	}
	if body.Context == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("context", "body"))
	}
	if body.UserID != nil {
		err = goa.MergeErrors(err, goa.ValidateFormat("body.user_id", *body.UserID, goa.FormatUUID))
	}
	if body.ResourceID != nil {
		err = goa.MergeErrors(err, goa.ValidateFormat("body.resource_id", *body.ResourceID, goa.FormatUUID))
	}
	if body.Action != nil {
		if !(*body.Action == "read" || *body.Action == "write" || *body.Action == "delete" || *body.Action == "execute" || *body.Action == "admin") {
			err = goa.MergeErrors(err, goa.InvalidEnumValueError("body.action", *body.Action, []any{"read", "write", "delete", "execute", "admin"}))
		}
	}
	if body.Context != nil {
		if err2 := ValidateConditionalAccessContextRequestBody(body.Context); err2 != nil {
			err = goa.MergeErrors(err, err2)
		}
	}
	return
}

